1	import 'dart:async';
2	
3	import 'package:cerne/core/design_tokens.dart';
4	import 'package:cerne/features/capture/presentation/bloc/insertion_modal_bloc.dart';
5	import 'package:cerne/features/capture/presentation/bloc/insertion_modal_event.dart';
6	import 'package:cerne/features/capture/presentation/bloc/insertion_modal_state.dart';
7	import 'package:cerne/features/capture/presentation/widgets/audio_tab_view.dart';
8	import 'package:cerne/features/capture/presentation/widgets/capture_tab_bar.dart';
9	import 'package:cerne/features/capture/presentation/widgets/foto_tab_view.dart';
10	import 'package:cerne/features/capture/presentation/widgets/texto_tab_view.dart';
11	import 'package:flutter/material.dart';
12	import 'package:flutter_bloc/flutter_bloc.dart';
13	
14	/// Shown via `showModalBottomSheet` as an overlay above Home/Chat (with a
15	/// darkened scrim) without discarding or navigating away from Home/Chat's
16	/// state underneath (FR-001) — `showModalBottomSheet` gives the scrim and
17	/// overlay semantics for free. An exhaustive `BlocBuilder` switch over
18	/// [InsertionModalState] drives the three tab bodies, plus a listener on
19	/// the bloc's one-shot [InsertionModalBloc.closeRequests] that pops the
20	/// sheet on a successful save (FR-011).
21	class InsertionModalPage extends StatefulWidget {
22	  const InsertionModalPage({super.key});
23	
24	  @override
25	  State<InsertionModalPage> createState() => _InsertionModalPageState();
26	}
27	
28	class _InsertionModalPageState extends State<InsertionModalPage> {
29	  late final StreamSubscription<void> _closeSubscription;
30	
31	  @override
32	  void initState() {
33	    super.initState();
34	    _closeSubscription = context.read<InsertionModalBloc>().closeRequests.listen(
35	      (_) {
36	        if (mounted && Navigator.of(context).canPop()) {
37	          Navigator.of(context).pop();
38	        }
39	      },
40	    );
41	  }
42	
43	  @override
44	  void dispose() {
45	    _closeSubscription.cancel();
46	    super.dispose();
47	  }
48	
49	  CaptureTab _tabOf(InsertionModalState state) => switch (state) {
50	    InsertionModalTexto() ||
51	    InsertionModalTextoSaving() ||
52	    InsertionModalTextoFailure() => CaptureTab.texto,
53	    InsertionModalAudioPermissionDenied() ||
54	    InsertionModalAudioRecording() ||
55	    InsertionModalAudioSaving() ||
56	    InsertionModalAudioFailure() => CaptureTab.audio,
57	    InsertionModalFotoCaptura() ||
58	    InsertionModalFotoPermissionDenied() ||
59	    InsertionModalFotoSaving() ||
60	    InsertionModalFotoFailure() => CaptureTab.foto,
61	  };
62	
63	  @override
64	  Widget build(BuildContext context) {
65	    return SafeArea(
66	      child: Padding(
67	        padding: const EdgeInsets.all(DesignTokens.spacingMd),
68	        child: Column(
69	          mainAxisSize: MainAxisSize.min,
70	          children: [
71	            Row(
72	              children: [
73	                Expanded(
74	                  child: Text('Nova entrada', style: DesignTokens.textTitleLg),
75	                ),
76	                IconButton(
77	                  onPressed: () {
78	                    context.read<InsertionModalBloc>().add(const ModalClosed());
79	                    Navigator.of(context).pop();
80	                  },
81	                  icon: const Icon(Icons.close),
82	                ),
83	              ],
84	            ),
85	            const SizedBox(height: DesignTokens.spacingMd),
86	            BlocBuilder<InsertionModalBloc, InsertionModalState>(
87	              builder: (context, state) {
88	                return Column(
89	                  mainAxisSize: MainAxisSize.min,
90	                  children: [
91	                    CaptureTabBar(
92	                      activeTab: _tabOf(state),
93	                      onTabSelected: (tab) =>
94	                          context.read<InsertionModalBloc>().add(TabSelected(tab)),
