import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

const _permissionDeniedMessage =
    'Permita o acesso ao microfone para gravar um áudio.';

/// A stop control, [AudioWaveform], and a running `mm:ss` timer for
/// [InsertionModalAudioRecording] (FR-004); the permission-denied message;
/// the plain generic loading indicator for [InsertionModalAudioSaving]
/// (FR-007); a plain failure message plus one generic retry action for
/// [InsertionModalAudioFailure], deliberately not reproducing the
/// prototype's named "Áudio — Erro" styling/copy (research.md R11).
class AudioTabView extends StatelessWidget {
  const AudioTabView({required this.state, super.key});

  final InsertionModalState state;

  @override
  Widget build(BuildContext context) {
    final bloc = context.read<InsertionModalBloc>();
    return Padding(
      padding: const EdgeInsets.all(DesignTokens.spacingMd),
      child: switch (state) {
        InsertionModalAudioPermissionDenied() => const CapturePermissionDeniedMessage(
          message: _permissionDeniedMessage,
        ),
        InsertionModalAudioRecording(elapsed: final elapsed) => _RecordingView(
          elapsed: elapsed,
          onStop: () => bloc.add(const AudioStopRequested()),
        ),
        InsertionModalAudioSaving() => const CaptureLoadingIndicator(),
        InsertionModalAudioFailure(message: final message) => CaptureFailureBand(
          message: message,
          onRetry: () => bloc.add(const RetryRequested()),
        ),
        _ => const SizedBox.shrink(),
      },
    );
  }
}

class _RecordingView extends StatelessWidget {
  const _RecordingView({required this.elapsed, required this.onStop});

  final Duration elapsed;
  final VoidCallback onStop;

  @override
  Widget build(BuildContext context) {
    final minutes = elapsed.inMinutes.toString().padLeft(2, '0');
    final seconds = (elapsed.inSeconds % 60).toString().padLeft(2, '0');

    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        const AudioWaveform(),
        const SizedBox(height: DesignTokens.spacingMd),
        Text('$minutes:$seconds', style: DesignTokens.textMonoCaption),
        const SizedBox(height: DesignTokens.spacingLg),
        IconButton(
          onPressed: onStop,
          icon: const Icon(Icons.stop_circle, color: DesignTokens.colorError),
          iconSize: DesignTokens.spacing2xl,
        ),
      ],
    );
  }
}

import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_bloc.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_event.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_state.dart';
import 'package:cerne/features/capture/presentation/widgets/capture_status_views.dart';
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

/// A free multiline text field and a "Salvar" action unavailable while the
/// field is empty (FR-003). Renders the plain generic loading indicator
/// while saving and a plain failure message on failure (FR-007/FR-009) —
/// tapping "Salvar" again is the retry, no dedicated retry affordance
/// needed for this tab.
class TextoTabView extends StatelessWidget {
  const TextoTabView({required this.state, super.key});

  final InsertionModalState state;

  @override
  Widget build(BuildContext context) {
    final bloc = context.read<InsertionModalBloc>();
    final text = switch (state) {
      InsertionModalTexto(text: final t) => t,
      InsertionModalTextoSaving(text: final t) => t,
      InsertionModalTextoFailure(text: final t) => t,
      _ => '',
    };
    final isSaving = state is InsertionModalTextoSaving;
    final failure = state;
    final failureMessage = failure is InsertionModalTextoFailure
        ? failure.message
        : null;

    return Padding(
      padding: const EdgeInsets.all(DesignTokens.spacingMd),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisSize: MainAxisSize.min,
        children: [
          TextFormField(
            key: const ValueKey('textoTabField'),
            initialValue: text,
            enabled: !isSaving,
            maxLines: 6,
            minLines: 3,
            decoration: const InputDecoration(
              hintText: 'Escreva sua entrada...',
            ),
            onChanged: (value) => bloc.add(TextDraftChanged(value)),
          ),
          if (failureMessage != null) ...[
            const SizedBox(height: DesignTokens.spacingSm),
            Text(
              failureMessage,
              style: DesignTokens.textBodyMd.copyWith(
                color: DesignTokens.colorError,
              ),
            ),
          ],
          const SizedBox(height: DesignTokens.spacingLg),
          if (isSaving)
            const CaptureLoadingIndicator()
          else
            ElevatedButton(
              onPressed: text.trim().isNotEmpty
                  ? () => bloc.add(const SaveTextSubmitted())
                  : null,
              child: const Text('Salvar'),
            ),
        ],
      ),
    );
  }
}

