7	/// Wraps [EntriesRemoteDataSource] and owns the in-memory [cachedEntries]
8	/// list — appended to only on a successful [create] (FR-011). Registered as
9	/// a `get_it` `lazySingleton` so the cache survives across modal opens (same
10	/// lifetime pattern as RF03's `VaultRepository`).
11	class EntriesRepositoryImpl implements EntriesRepository {
12	  EntriesRepositoryImpl(this._remoteDataSource);
13	
14	  final EntriesRemoteDataSource _remoteDataSource;
15	
16	  final List<Entry> _cachedEntries = [];
17	
18	  @override
19	  Future<Either<Failure, Entry>> create({
20	    required String content,
21	    required EntrySource source,
22	  }) async {
23	    final result = await _remoteDataSource.create(
24	      content: content,
25	      source: source,
26	    );
27	    return result.map((entry) {
28	      _cachedEntries.add(entry);
29	      return entry;
30	    });
31	  }
32	
33	  @override
34	  List<Entry> get cachedEntries => List.unmodifiable(_cachedEntries);
35	}
