15	/// one-time "copy the bundled model asset to a writable app-support
16	/// directory" step (research.md R2); subsequent calls reuse the copied
17	/// file.
18	class WhisperTranscriptionDataSource {
19	  WhisperTranscriptionDataSource({WhisperController? controller})
20	    : _controller = controller ?? WhisperController();
21	
22	  final WhisperController _controller;
23	  bool _modelCopied = false;
24	
25	  Future<String> transcribe(String audioFilePath) async {
